import { createChart, removeChart } from '../test/ut/core/utHelper';

// Safeguard for upstream fix "fix(pie): fix `endAngle` is not applied on the empty circle".
// The empty-circle placeholder should use the same startAngle/endAngle sweep as a
// normal pie layout instead of always rendering a full ring.
describe('pie-empty-circle-endangle', function () {

    const RADIAN = Math.PI / 180;

    function getEmptyCircleShape(chart: ReturnType<typeof createChart>) {
        chart.getZr().refreshImmediately();
        const chartsViews = (chart as any)._chartsViews as any[];
        const pieView = chartsViews.filter(function (view) {
            return view._emptyCircleSector;
        })[0];
        return pieView._emptyCircleSector.shape;
    }

    it('applies a non-default endAngle to the empty circle', function () {
        const chart = createChart({ width: 400, height: 300 });
        chart.setOption({
            series: [{
                type: 'pie',
                startAngle: 90,
                endAngle: 0,
                radius: ['40%', '70%'],
                data: []
            }]
        } as any);
        const shape = getEmptyCircleShape(chart);
        expect(shape.startAngle).toBeCloseTo(-90 * RADIAN, 5);
        expect(shape.endAngle).toBeCloseTo(0, 5);
        removeChart(chart);
    });

    it('keeps a full sweep for the default endAngle (auto)', function () {
        const chart = createChart({ width: 400, height: 300 });
        chart.setOption({
            series: [{
                type: 'pie',
                data: []
            }]
        } as any);
        const shape = getEmptyCircleShape(chart);
        // 'auto' resolves to startAngle - 2 * PI, i.e. a full circle as before.
        expect(shape.startAngle).toBeCloseTo(-90 * RADIAN, 5);
        expect(shape.endAngle).toBeCloseTo(-90 * RADIAN - Math.PI * 2, 5);
        removeChart(chart);
    });
});

